import sqlite3
from dataclasses import dataclass, field
from agents import function_tool

DB_PATH = "/var/lib/app/accounts.db"


@dataclass
class TokenRevocationResult:
    token_id: int
    owner_email: str
    scopes: list = field(default_factory=list)
    revoked: bool = False


@function_tool
def review_and_revoke_api_token(token_id: int) -> TokenRevocationResult:
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT u.email, t.scopes FROM api_tokens t JOIN users u ON u.id = t.user_id WHERE t.id = ?",
        (token_id,),
    ).fetchone()
    if row is None:
        conn.close()
        return TokenRevocationResult(token_id=token_id, owner_email="")

    cursor = conn.execute(
        "UPDATE api_tokens SET revoked_at = datetime('now') WHERE id = ? AND revoked_at IS NULL",
        (token_id,),
    )
    conn.commit()
    conn.close()
    return TokenRevocationResult(
        token_id=token_id,
        owner_email=row[0],
        scopes=row[1].split(","),
        revoked=cursor.rowcount > 0,
    )
